22	
23	MEMORY
24	{
25	    kflash (rx) : ORIGIN = 0x80200000, LENGTH = 2048K   /* w/ cache */
26	    ksram (rwx) : ORIGIN = 0x80400000, LENGTH = 2048K   /* w/ cache */
27	    pgram (rwx) : ORIGIN = 0x80600000, LENGTH = 4096K   /* w/ cache */
28	    ramdisk (rwx) : ORIGIN = 0x80A00000, LENGTH = 16M   /* w/ cache */
29	}
30	
31	OUTPUT_ARCH("riscv")
32	
33	/* Provide the kernel boundaries */
34	
35	__kflash_start = ORIGIN(kflash);
36	__kflash_size = LENGTH(kflash);
37	__ksram_start = ORIGIN(ksram);
38	__ksram_size = LENGTH(ksram);
39	__ksram_end = ORIGIN(ksram) + LENGTH(ksram);
40	
41	/* Page heap */
42	
43	__pgheap_start = ORIGIN(pgram);
44	__pgheap_size = LENGTH(pgram) + LENGTH(ramdisk);
45	
46	/* Application ramdisk */
47	
48	__ramdisk_start = ORIGIN(ramdisk);
49	__ramdisk_size = LENGTH(ramdisk);
50	__ramdisk_end  = ORIGIN(ramdisk) + LENGTH(ramdisk);
51	
52	SECTIONS
53	{
54	  . = 0x80200000;
55	
56	  /* where the global variable out-of-bounds detection information located */
57	
58	#ifdef CONFIG_MM_KASAN_GLOBAL
59	  .kasan.unused : {
60	    *(.data..LASANLOC*)
61	  }
62	  .kasan.global : {
63	    KEEP (*(.data..LASAN0))
64	    KEEP (*(.data.rel.local..LASAN0))
65	  }
66	  .kasan.shadows : {
67	    *(.kasan.shadows)
68	  }
69	#endif
70	
71	  .text :
72	    {
73	      _stext = . ;
74	      *(.text)
75	      *(.text.*)
76	      *(.gnu.warning)
77	      *(.stub)
78	      *(.glue_7)
79	      *(.glue_7t)
80	      *(.jcr)
81	
82	      /* C++ support:  The .init and .fini sections contain specific logic
83	       * to manage static constructors and destructors.
84	       */
85	
86	      *(.gnu.linkonce.t.*)
87	      *(.init)             /* Old ABI */
88	      *(.fini)             /* Old ABI */
89	      _etext = . ;
90	    }
91	
92	  .rodata :
93	    {
94	      _srodata = . ;
95	      *(.rodata)
96	      *(.rodata1)
97	      *(.rodata.*)
98	      *(.gnu.linkonce.r*)
99	      _erodata = . ;
100	    }
101	
102	  .tdata :
103	    {
104	      _stdata = ABSOLUTE(.);
105	      *(.tdata .tdata.* .gnu.linkonce.td.*);
106	      _etdata = ABSOLUTE(.);
107	    }
108	
109	  .tbss :
110	    {
111	      _stbss = ABSOLUTE(.);
112	      *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
113	      _etbss = ABSOLUTE(.);
114	    }
115	
116	  _eronly = ABSOLUTE(.);
117	
118	  .data :
119	    {
120	      _sdata = . ;
121	      *(.data)
122	      *(.data1)
123	      *(.data.*)
124	      *(.gnu.linkonce.d*)
125	      . = ALIGN(4);
126	      _edata = . ;
127	    }
128	
129	  .bss :
130	    {
131	      _sbss = . ;
132	      *(.bss)
133	      *(.bss.*)
134	      *(.sbss)
135	      *(.sbss.*)
136	      *(.gnu.linkonce.b*)
137	      *(COMMON)
138	      . = ALIGN(32);
139	      _ebss = . ;
140	    } > ksram
141	
142	  /* Page tables here, align to 4K boundary */
143	
144	  .pgtables (NOLOAD) : ALIGN(0x1000)
145	    {
146	      *(.pgtables)
147	      . = ALIGN(4);
148	    } > ksram
149	
150	  /* Stack top */
151	
152	  .stack_top :
153	    {
154	      . = ALIGN(32);
155	      _ebss = ABSOLUTE(.);
156	    } > ksram
157	
158	  /* Stabs debugging sections.    */
159	
160	  .stab 0 : { *(.stab) }
161	  .stabstr 0 : { *(.stabstr) }
162	  .stab.excl 0 : { *(.stab.excl) }
163	  .stab.exclstr 0 : { *(.stab.exclstr) }
164	  .stab.index 0 : { *(.stab.index) }
165	  .stab.indexstr 0 : { *(.stab.indexstr) }
166	  .comment 0 : { *(.comment) }
167	  .debug_abbrev 0 : { *(.debug_abbrev) }
168	  .debug_info 0 : { *(.debug_info) }
169	  .debug_line 0 : { *(.debug_line) }
170	  .debug_pubnames 0 : { *(.debug_pubnames) }
171	  .debug_aranges 0 : { *(.debug_aranges) }
172	}
