/****************************************************************************
 * Replacement libgcc functions compiled with -mcmodel=medany.
 *
 * The pre-compiled libgcc.a from the toolchain is built with
 * -mcmodel=medlow, which uses absolute addressing (R_RISCV_HI20).
 * When the kernel is linked at 0x80200000 (> 2GB boundary), the
 * absolute address of the __clz_tab lookup table cannot be encoded
 * in the LUI instruction's 20-bit immediate field.
 *
 * By providing our own implementations compiled with -mcmodel=medany,
 * all addressing is PC-relative and works at any address.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdint.h>

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: __clzdi2
 *
 * Description:
 *   Count leading zeros in a 64-bit value (double integer).
 *   This is a compiler support function called by GCC for __builtin_clzll
 *   when the hardware does not provide a CLZ instruction.
 *
 ****************************************************************************/

int __clzdi2(uint64_t val)
{
  int count = 0;
  int i;

  if (val == 0)
    {
      return 64;
    }

  for (i = 63; i >= 0; i--)
    {
      if (val & (1ULL << i))
        {
          break;
        }

      count++;
    }

  return count;
}

/****************************************************************************
 * Name: __ctzdi2
 *
 * Description:
 *   Count trailing zeros in a 64-bit value (double integer).
 *   This is a compiler support function called by GCC when the hardware
 *   does not provide a CTZ instruction.
 *
 ****************************************************************************/

int __ctzdi2(uint64_t val)
{
  int count = 0;

  if (val == 0)
    {
      return 64;
    }

  while ((val & 1) == 0)
    {
      val >>= 1;
      count++;
    }

  return count;
}

/****************************************************************************
 * Name: __ffsdi2
 *
 * Description:
 *   Find first set bit in a 64-bit value (1-based, returns 0 if val==0).
 *   This is a compiler support function called by GCC for __builtin_ffsll
 *   when the hardware does not provide a CTZ instruction.
 *
 ****************************************************************************/

int __ffsdi2(uint64_t val)
{
  if (val == 0)
    {
      return 0;
    }

  return __ctzdi2(val) + 1;
}

/****************************************************************************
 * Name: __popcountdi2
 *
 * Description:
 *   Population count (number of set bits) in a 64-bit value.
 *   This is a compiler support function.
 *
 ****************************************************************************/

int __popcountdi2(uint64_t val)
{
  int count = 0;

  while (val)
    {
      val &= val - 1;
      count++;
    }

  return count;
}

/****************************************************************************
 * Name: __paritydi2
 *
 * Description:
 *   Parity of a 64-bit value (1 if odd number of bits set).
 *   This is a compiler support function.
 *
 ****************************************************************************/

int __paritydi2(uint64_t val)
{
  return __popcountdi2(val) & 1;
}

text:
工具链的 `__clzdi2` 使用了查表优化，而查表就需要直接寻址 `.rodata` 中的 `__clz_tab`。以下是对比：

| | prebuilts 工具链 libgcc | 我提供的内核级替换 |
|---|---|---|
| **代码模型** | `-mcmodel=medlow` (编译时固定) | `-mcmodel=medany` (随内核编译选项) |
| **寻址方式** | **绝对寻址** (LUI 加载绝对地址高位) | **PC-relative** (相对寻址) |
| **实现方式** | 查表法：`__clz_tab[256]` 在 `.rodata` | 逐位循环：纯算法，不依赖数据表 |
| **性能** | O(1) 单次查表 | O(n) 最多 64 次循环 |
| **代码体积** | 小（查表指令）+ 256 字节数据表 | 稍大（循环逻辑） |
| **能否在 0x80200000 工作** | ❌ 绝对地址超出 32 位有符号范围 | ✅ PC-relative 不受地址影响 |

### 工具链的实现 (medlow, 查表, 失败)

```c
// 简化示意：GCC libgcc 的 __clzdi2 查表法
const unsigned char __clz_tab[256] = { 8,7,6,6,5,5,5,5,4,4,4,4,... };
// __clz_tab 在 .rodata 段，链接地址 0x8020xxxx

int __clzdi2(uint64_t val) {
    // LUI + ADDI 绝对寻址加载 __clz_tab 地址
    // → R_RISCV_HI20 重定位，地址 > 2GB 无法编码
    return __clz_tab[val >> 56] + ...;
}
```

```asm
# 工具链 libgcc 实际汇编
lui  a0, %hi(__clz_tab)    # 加载 __clz_tab 地址高 20 位
                            # __clz_tab = 0x8020_xxxx >> 12 = 0x80200
                            # 超出 signed 20-bit 范围 (max 0x7FFFF)
                            # ❌ R_RISCV_HI20 relocation truncated!
addi a0, a0, %lo(__clz_tab) # 加载低 12 位
```

### 我的实现 (medany, 纯算法, 成功)

```c
int __clzdi2(uint64_t val) {
    // 纯算法：不引用任何全局数据，不需要重定位
    int count = 0;
    if (val == 0) return 64;
    for (int i = 63; i >= 0; i--) {
        if (val & (1ULL << i)) break;
        count++;
    }
    return count;
}
```

```asm
# 生成的汇编：完全使用寄存器和立即数，无全局引用
li   a1, 63          # 立即数
srl  a2, a0, a1      # 纯寄存器操作
bnez a2, .L_done     # PC-relative 跳转
# ✅ 不需要任何重定位！
```

### 本质区别

不是算法问题——是**寻址模型**问题。工具链的 libgcc 在编译时就已经固化了绝对寻址，而内核链接在 2GB 以上。我的替换函数随内核一起用 `-mcmodel=medany` 编译，自然避开了这个问题。

### 性能影响

在内核启动路径（如 NSH 初始化期间的 `__ffsdi2` 调用）中，逐位循环替代查表会慢一些，但：
- 这些函数只在初始化阶段和少量路径上调用
- 内核不是热路径性能敏感场景
- 每次调用最多 64 次循环（实际平均 32 次），在 1GHz C906 核心上约几百纳秒
